Vì sao đoạn mã cần hai typedef, và chương trình in ra gì?
import 'dart:ffi';
typedef Sum Native = Int32 Function(Int32 a, Int32 b);
typedef Sum Dart = int Function(int a, int b);
final lib = Dynamic Library.open('libmath.so');
final sum = lib.lookup Function<Sum Native, Sum Dart>('sum');
void main() => print(sum(3, 4));

